ph=json.load(open('loops/frontend-dev/state/001-quickflow/phases.json'))['phases']
for p in ph:
  if p['phase']=='phase-00': continue
  f=open(f"loops/frontend-dev/outputs/001-quickflow/{p['phase']}.md").read()
  ids=re.findall(r'^- \[[ ~xX]\] (T\d+)',f,re.M)
  if ids!=p['task_ids']: print('ids differ',p['phase'],ids,p['task_ids'])
  for m in re.finditer(r'^- \[[ ~xX]\] (T\d+)(.*)$',f,re.M):
    tt=tasks.get(m.group(1),'')
    if m.group(2).strip() not in tt: print('text differs',m.group(1))
print(len(tasks))
EOF

